          more: "ECOFERT®是一种微剂量液态有机肥料，含有游离氨基酸（8%）、总氮（1.73%，其中大部分为有机形式，占1.66%），pH值接近9。其配方结合了赖氨酸、精氨酸、苏氨酸、甘氨酸、异亮氨酸和亮氨酸——这些氨基酸可被植物直接吸收，在开花、坐果等关键阶段为植物提供支持，且与传统螯合肥料不同，绝不会耗尽土壤。该产品获SOHISCERT认证，并符合欧盟有机生产法规（欧盟2018/848），已在约六十个国家使用，每公顷施用1至4瓶（每瓶140毫升）——对果树、柑橘类和蔬菜而言，通常两次施用即可（一次在开花或播种前施于土壤，另一次在种植中期通过叶面喷施）；在热带地区，最多可每三个月施用一瓶。该产品对使用者和环境均无明显危害，不易燃，运输或储存均无特殊限制。ECOFERT®与我们的EVERGREEN®和ECOSORB®保水剂结合使用后，在萨赫勒地区记录到的产量提升最高达100%，实地测得的产量增幅达60%。",
