          q: "「我以前用过的水凝胶把我的植株都闷坏了。」",
          a: "这正是钠基产品的缺陷：一旦水合，就会形成使植株窒息的糊状物。而丙烯酰胺基产品即便获准使用，也仅限于非食用作物。我们的两款配方均以钾为基础，既适用于食用作物，也不会伤害土壤中的微动物群。",
