          more: "Το NAPEMA® (Natural Pest Management) είναι μια ανατρεπτική προσέγγιση στην προστασία των καλλιεργειών: ούτε συνθετικά μόρια, ούτε κλασική βιολογική καταπολέμηση με ωφέλιμα έντομα — μια μέθοδος αναγνωρισμένη για την οικολογική της αξία, αλλά με περιορισμένη αποτελεσματικότητα καθώς οι θηρευτές δεν είναι πάντα παρόντες τη σωστή στιγμή ούτε σε επαρκή αριθμό, και που σχεδόν ποτέ δεν επιτρέπει τον έλεγχο ασθενειών. Το NAPEMA® δρα μέσω ψεκασμού φυλλώματος και ρίζας, προληπτικά και θεραπευτικά, κατά ασθενειών, παρασίτων, μυκήτων και επιβλαβών εντόμων, χωρίς να αφήνει κατάλοιπα ούτε στο έδαφος, ούτε στο φυτό, ούτε στον αέρα. Η πραγματική του δύναμη είναι η εξατομίκευση: κάθε λύση διαμορφώνεται για να απαντήσει σε ένα συγκεκριμένο πρόβλημα, περιστασιακό ή επαναλαμβανόμενο — η κοχενίλια των φραγκοσυκιών, το HLB (citrus greening) που απειλεί τα εσπεριδοειδή, ή οι νηματώδεις που προσβάλλουν ντομάτες και ζαχαροκάλαμο είναι παραδείγματα που αντιμετωπίστηκαν με επιτυχία. Το αποτέλεσμα είναι μια προστασία που διατηρεί την ωφέλιμη πανίδα και χλωρίδα — επικονιαστές και ωφέλιμα έντομα συμπεριλαμβανομένων — χωρίς να διαταράσσει τον φυσικό κύκλο γονιμότητας του εδάφους, με προσιτό κόστος που προστατεύει, αντί να επιβαρύνει, την αποδοτικότητα της καλλιέργειας.",
