          more: "Η αγροδασοπονία είναι το πεδίο εφαρμογής όπου συνδυάζονται όλες οι τεχνολογίες μας. Κάθε πρόγραμμα αναδάσωσης ή ανάκτησης υποβαθμισμένων εδαφών συνδυάζει το Paulownia ALTIFOLIA® ή τοπικά είδη, τους υδροσυγκρατητές μας EVERGREEN®/ECOSORB® που παρέχονται από τη φύτευση, και τα λιπάσματά μας ECOFERT® για τη στήριξη της ριζοβολίας — αρκετά για την εγκατάσταση ενός λειτουργικού αγροδασικού οικοσυστήματος σε λιγότερο από 24 μήνες, ακόμη και σε αμμώδη ή έντονα υποβαθμισμένα εδάφη όπου η συμβατική δενδροκομία αποτυγχάνει. Κάθε φυτό ξεκινά εξοπλισμένο με τη δόση υδροσυγκρατητή του, γεγονός που εξαλείφει τον κίνδυνο υδατικής καταπόνησης κατά την κρίσιμη περίοδο εγκατάστασης και ανεβάζει το ποσοστό επιβίωσης πάνω από 95 %. Πέρα από την ξυλεία και τα έσοδα που παράγει μακροπρόθεσμα, αυτός ο τύπος προγράμματος σταθεροποιεί διαρκώς τα εδάφη ενάντια στη διάβρωση και την απερήμωση, αποκαθιστά την υπόγεια και εναέρια βιοποικιλότητα, και ανοίγει την πρόσβαση σε πιστώσεις άνθρακα και παραγωγή μελιού (έως 400-700 kg ανά εκτάριο με το Paulownia) που διαφοροποιούν τα έσοδα των εκμεταλλεύσεων.",
